SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'F' AND p.anchor_year = 40 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND a.admission_type = 'CABG' AND a.hadm_id IN (SELECT MIN(hadm_id) FROM admissions WHERE subject_id = a.subject_id);